import math

import pytest

from epidemic.final_size import final_size
from epidemic.sir_euler import simulate_attack_rate


# ---------------------------------------------------------------- reference
def _reference_final_size(r0):
    """High-precision root of z = 1 - exp(-R0 z) via bisection (independent)."""
    lo, hi = 0.0, 1.0 - 1e-16

    def f(z):
        return 1.0 - math.exp(-r0 * z) - z

    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


# --------------------------------------------------------------- unit tests
@pytest.mark.parametrize("r0", [0.5, 1.0, 0.999, 0.0, -2.0])
def test_no_epidemic_below_threshold(r0):
    assert final_size(r0) == 0.0


def test_known_value_r0_2():
    # Classic textbook value: z = 1 - e^{-2z}  =>  z ~ 0.7968...
    assert abs(final_size(2.0) - 0.7968) < 1e-3


def test_matches_independent_bisection_solver():
    for r0 in [1.05, 1.2, 1.5, 2.0, 3.0, 5.0, 10.0]:
        assert abs(final_size(r0) - _reference_final_size(r0)) < 1e-8


def test_result_is_valid_fraction_and_fixed_point():
    for r0 in [1.5, 2.0, 3.0, 7.5]:
        z = final_size(r0)
        assert 0.0 < z < 1.0
        # Residual of the defining equation.
        assert abs(z - (1.0 - math.exp(-r0 * z))) < 1e-8


def test_monotonicity_in_r0():
    grid = [1.0 + i * 0.1 for i in range(1, 41)]  # 1.1 .. 5.0
    sizes = [final_size(r0) for r0 in grid]
    assert sizes == sorted(sizes)
    # Strictly increasing away from the threshold.
    assert all(b > a for a, b in zip(sizes[1:], sizes[:-1]))


def test_non_convergence_raises():
    with pytest.raises(RuntimeError):
        final_size(2.0, max_iter=3)


# --------------------------------------------------- simulation cross-check
@pytest.mark.parametrize("r0", [1.5, 2.0, 3.0])
def test_matches_euler_sir_simulation(r0):
    n = 1_000_000
    analytic = final_size(r0)
    simulated = simulate_attack_rate(r0, n=n)
    assert abs(analytic - simulated) < 0.005, (
        f"R0={r0}: analytic={analytic:.6f}, simulated={simulated:.6f}"
    )

